<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Crown, Sparkles } from 'lucide-vue-next'
import { useRoomStore } from '../stores/room.js'
import { useAuthStore } from '../stores/auth.js'
import { finishGame, loadAllResults, replayGame, startNextRound } from '../services/game.js'
import CharacterAvatar from '../components/common/CharacterAvatar.vue'
import { audioManager } from '../audio/manager.js'
import { syncRoomRoute } from '../utils/roomRoute.js'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),roomStore=useRoomStore(),busy=ref(false),error=ref(''),results=ref([]),code=computed(()=>String(route.params.code).toUpperCase()),totals=computed(()=>results.value.reduce((all,result)=>{for(const [uid,categories] of Object.entries(result.scores||{}))all[uid]=(all[uid]||0)+Object.values(categories).reduce((sum,value)=>sum+Number(value||0),0);return all},{})),sorted=computed(()=>roomStore.players.map(player=>({...player,totalScore:totals.value[player.uid]||0})).sort((a,b)=>b.totalScore-a.totalScore)),hasNext=computed(()=>(roomStore.room?.roundNumber||0)<(roomStore.room?.totalRounds||0));let releaseRoom,loadedRound=0,loadedGameId=''
onMounted(async()=>{await auth.initialize();releaseRoom=roomStore.subscribe(code.value)});onBeforeUnmount(()=>releaseRoom?.())
watch(()=>roomStore.room,async room=>{syncRoomRoute(router,route.path,room,code.value);if(!['results','finished'].includes(room?.status))return;const event=`results:${code.value}:${room.currentRoundId}`;audioManager.playOnce(hasNext.value?'results':'winner',event);if(room.roundNumber!==loadedRound||room.gameId!==loadedGameId){loadedRound=room.roundNumber;loadedGameId=room.gameId||'';try{results.value=await loadAllResults(code.value,room.roundNumber,room.gameId)}catch(e){error.value=e.message}}},{deep:true})
async function next(){busy.value=true;error.value='';try{await startNextRound(code.value)}catch(e){error.value=e.message}finally{busy.value=false}}
async function finish(){busy.value=true;error.value='';try{await finishGame(code.value)}catch(e){error.value=e.message}finally{busy.value=false}}
async function replay(){busy.value=true;error.value='';try{await replayGame(code.value)}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="page-wrap results-page"><section class="page-heading"><span class="sticker"><Sparkles/> {{roomStore.room?.status==='finished'?'النتيجة النهائية':'النتيجة ظهرت'}}</span><h1>إيه الحرفنة دي!</h1><p>{{hasNext?'لسه المنافسة مولعة والجولة الجاية هتفرق.':'خلصت اللعبة وده الترتيب النهائي.'}}</p></section><div class="leaderboard"><article v-for="(player,index) in sorted" :key="player.uid" :class="{winner:index===0}"><b class="rank">{{ index+1 }}</b><CharacterAvatar :id="player.avatar" :size="52"/><strong>{{ player.nickname }} <Crown v-if="index===0"/></strong><b>{{ player.totalScore }} نقطة</b></article></div><p v-if="error" class="error-message">{{error}}</p><button v-if="roomStore.isHost&&hasNext" class="btn btn-primary btn-lg" :disabled="busy" @click="next">{{busy?'بنجهز...':'ابدأ الجولة الجاية'}}</button><p v-else-if="hasNext">استنى الأدمن يبدأ الجولة الجاية.</p><template v-else-if="roomStore.isHost&&roomStore.room?.status!=='finished'"><button class="btn btn-primary btn-lg" :disabled="busy" @click="finish">{{busy?'بننهي...':'اللعبة خلصت'}}</button><button class="btn btn-soft btn-lg" :disabled="busy" @click="replay">العب تاني بنفس القعدة</button></template><button v-else-if="roomStore.isHost" class="btn btn-soft btn-lg" :disabled="busy" @click="replay">العب تاني بنفس القعدة</button><p v-else-if="roomStore.room?.status!=='finished'">استنى الأدمن يعتمد نهاية اللعبة.</p><RouterLink v-if="roomStore.room?.status==='finished'" to="/" class="btn btn-primary btn-lg">الخروج من اللعبة</RouterLink></div></template>
